parameters.query:
INSERT INTO konversationen (konversation_id, state)
VALUES (
  '{{ $json.message.chat.id }}',
  '{{ JSON.stringify({
    "konversation_id": $json.message.chat.id.toString(),
    "status": "in_bearbeitung",
    "kunde": {
      "telegram_user_id": $json.message.from.id.toString(),
      "telegram_name": $json.message.from.first_name
    },
    "anfrage": {
      "datum_text": null, "datum_iso": null, "anlass": null,
      "personenanzahl": null, "budget": null, "ort": null,
      "speisen_wuensche": null, "allergien": null, "sonstige_wuensche": null
    },
    "fehlende_felder": ["datum","anlass","personenanzahl","budget","ort","speisen_wuensche","allergien","sonstige_wuensche"],
    "letzte_aktualisierung": ""
  }).replace(/'/g, "''") }}'::jsonb
)
ON CONFLICT (konversation_id) DO UPDATE
  SET aktualisiert_am = NOW()
RETURNING state;
